	// (POST /trex/init/contract/factory/identity)
	DeployIdentityFactory(c *gin.Context)
	// Deploy TREX factory
	// (POST /trex/init/contract/factory/trexFactory)
	DeployAndInitTrexFactoryAsync(c *gin.Context)
